    public static final String[][] l = new String[][]{{"Con mau g\u1eb7p c\u00f4 Ayumi \u0111\u1ec3 kh\u00f4i ph\u1ee5c s\u1ee9c m\u1ea1nh \u0111i.."}, {"C\u00f4 Ayumi \u0111\u1ee9ng \u0111\u1eb1ng kia. H\u00e3y mau \u0111\u1ebfn g\u1eb7p c\u00f4 \u1ea5y!"}, {"Con m\u1edbi b\u1ecb th\u01b0\u01a1ng n\u1eb7ng, kh\u00f4ng n\u00ean t\u1eadp luy\u1ec7n qu\u00e1 nhi\u1ec1u!", "H\u00e3y ngh\u1ec9 ng\u01a1i m\u1ed9t th\u1eddi gian r\u1ed3i g\u1eb7p ta!"}, {"Con t\u1ec9nh r\u1ed3i \u0111\u1ea5y \u00e0!", "Tuy l\u1ea7n n\u00e0y b\u1ecb th\u01b0\u01a1ng kh\u00e1 n\u1eb7ng, nh\u01b0ng con v\u1eabn c\u00f3 th\u1ec3 h\u1ed3i ph\u1ee5c \u0111\u01b0\u1ee3c.", "G\u1ea7n \u0111\u00e2y, b\u1ecdn nh\u00edm l\u00f4ng n\u00e2u sinh s\u1ea3nh \u1ed3 \u1ea1t, ph\u00e1 ho\u1ea1i m\u00f9a m\u00e0ng..", "Con h\u00e3y t\u00ecm gi\u1ebft 10 con nh\u00edm, nh\u01b0 con \u0111\u00e3 t\u1eebng l\u00e0m..", "R\u1ed3i ta s\u1ebd gi\u00fap con h\u1ed3i ph\u1ee5c kh\u1ea3 n\u0103ng khinh c\u00f4ng!"}, {"Nhanh l\u00ean, sang khu luy\u1ec7n t\u1eadp v\u00e0 gi\u1ebft nh\u1eefng con nh\u00edm ph\u00e1 ho\u1ea1i m\u00f9a m\u00e0ng.."}, {"T\u1ed1t l\u1eafm, con \u0111\u00e3 h\u1ed3i ph\u1ee5c t\u01b0\u01a1ng \u0111\u1ed1i th\u1ec3 l\u1ef1c.", "Khinh c\u00f4ng c\u1ee7a con tuy kh\u00f4ng nhu\u1ea7n nhuy\u1ec5n nh\u01b0 x\u01b0a..", "..nh\u01b0ng n\u1ebfu t\u1eadp luy\u1ec7n \u0111\u1ec1u \u0111\u1eb7n, s\u1ebd mang l\u1ea1i k\u1ebft qu\u1ea3.", "Th\u1ea7y hi\u1ec7u tr\u01b0\u1edfng g\u1ecdi con \u0111\u1ea5y, \u0111\u1ebfn \u0111\u00f3 nhanh l\u00ean!"}, {"Con h\u00e3y l\u00e0m xong nhi\u1ec7m v\u1ee5 \u0111\u01b0\u1ee3c giao, r\u1ed3i \u0111\u1ebfn \u0111\u00e2y g\u1eb7p ta sau!"}, {"Onda! Chuy\u1ec7n l\u1ea7n tr\u01b0\u1edbc ta giao, con v\u1eabn l\u00e0 ng\u01b0\u1eddi th\u1ef1c hi\u1ec7n.", "Nh\u01b0ng l\u1ea7n n\u00e0y, con h\u00e3y d\u1eabn theo Sakura \u0111i c\u00f9ng.", "H\u00e3y \u0111i g\u1ecdi n\u00f3 quay v\u1ec1 \u0111\u00e2y g\u1eb7p ta! Con b\u00e9 \u1ea5y b\u00ean khu th\u00e1c n\u01b0\u1edbc."}, {"H\u00e3y t\u00ecm Sakura b\u00ean d\u01b0\u1edbi th\u00e1c n\u01b0\u1edbc r\u1ed3i quay v\u1ec1 \u0111\u00e2y g\u1eb7p ta!"}, {"Uhm t\u1ed1t l\u1eafm.. C\u00e1c con c\u00f3 th\u1ec3 s\u1eb5n s\u00e0ng l\u00ean \u0111\u01b0\u1eddng r\u1ed3i.", "Tuy nhi\u00ean, s\u1ee9c m\u1ea1nh c\u1ee7a Onda v\u1eabn ch\u01b0a h\u1ed3i ph\u1ee5c h\u1eb3n..", "..c\u00e1c con c\u00f2n nh\u1edb Toniku ch\u1ee9! H\u00e3y g\u1ecdi n\u00f3 \u0111\u1ebfn \u0111\u00e2y!", "Toniku s\u1ebd \u0111i c\u00f9ng c\u00e1c con!"}, {"T\u1ed1t l\u1eafm, c\u00e1c con \u0111\u00e3 \u0111\u1ee7 1 nh\u00f3m!", "Tuy nhi\u00ean th\u1ec3 l\u1ef1c Onda c\u00f2n h\u01a1i y\u1ebfu, n\u00ean h\u00e3y luy\u1ec7n t\u1eadp th\u00eam..", "Khi n\u00e0o con \u0111\u01b0\u1ee3c c\u1ea5p \u0111\u1ed9 6, ta s\u1ebd cho ph\u00e9p l\u00ean \u0111\u01b0\u1eddng!", "Toniku v\u00e0 Sakura c\u00f9ng gi\u00fap b\u1ea1n luy\u1ec7n t\u1eadp nh\u00e9!"}, {"\u0110\u00e2y l\u00e0 th\u00f4ng h\u00e0nh c\u1ee7a ta. C\u00e1c con c\u00f3 th\u1ec3 l\u00ean \u0111\u01b0\u1eddng!", "Onda, l\u1ea7n n\u00e0y con kh\u00f4ng \u0111\u01b0\u1ee3c ch\u1ee7 quan.", "Sakura v\u00e0 Toniku h\u1ed7 tr\u1ee3 t\u1ed1t Onda nh\u00e9", "Ta nghe n\u00f3i c\u00e2y c\u1ea7u b\u1eaft qua s\u00f4ng Watamaro \u0111\u00e3 b\u1ecb g\u00e3y..", "V\u00ec th\u1ebf c\u00e1c con h\u00e3y men theo con \u0111\u01b0\u1eddng b\u00ean d\u01b0\u1edbi ch\u00e2n c\u1ea7u m\u00e0 \u0111i.", "Ch\u00fac c\u00e1c con may m\u1eafn!"}, {"H\u00e3y t\u00ecm Toniku \u1edf th\u00f4n Sanzuya r\u1ed3i c\u00f9ng quay v\u1ec1 \u0111\u00e2y g\u1eb7p ta!"}, {"H\u00e3y nhanh ch\u00f3ng c\u00f9ng b\u1ea1n b\u00e8 \u0111\u1ebfn tr\u01b0\u1eddng Haruna!"}, {"H\u00e3y mau \u0111i g\u1eb7p Toniku \u0111i, n\u00f3 \u0111ang \u0111\u1ee3i c\u00e1c con \u1edf b\u00ean d\u00e3y l\u1edbp h\u1ecdc \u0111\u00f3"}, {"Ta \u0111ang nh\u1ee9c \u0111\u1ea7u, kh\u00f4ng mu\u1ed1n b\u00e1n bu\u00f4n g\u00ec h\u1ebft", "\u0110\u1ebfn ch\u1ed7 kh\u00e1c m\u00e0 mua"}};
    public static final String[][] m = new String[][]{{"C\u1ee9 \u0111i \u0111\u01b0\u1eddng n\u00e0y s\u1ebd \u0111\u1ebfn tr\u01b0\u1eddng Haruna, ch\u00fac may m\u1eafn!"}};
